n = int(input())
q = list(map(int, input().split()))
a = list(map(int, input().split()))
b = list(map(int, input().split()))

def solve(servings, q, a, b):
    for i in range(len(q)):
        if servings * (a[i] + b[i]) > q[i]:
            return False
    return True

ok = 0
no = min(q[i] // (a[i] + b[i]) for i in range(n)) + 1
mid = (ok + no) // 2
while ok + 1 < no:
    if solve(mid, q, a, b):
        ok = mid
    else:
        no = mid
    mid = (ok + no) // 2

print(ok)
